INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('controle-hydraulique', 'fr', 'Contrôle-Commande Temps Réel, Procédé Hydraulique Bicuve', 'Automatisme & Régulation', 'De la modélisation Matlab/Simulink au pilotage temps réel sur cible industrielle Speedgoat.', 'Projet complet d''automatique portant sur un système hydraulique à deux cuves couplées. De la modélisation physique et l''analyse de stabilité jusqu''au déploiement d''un régulateur numérique en temps réel sur une cible Speedgoat, en passant par l''identification expérimentale et la synthèse de correcteurs continus et discrets.', 'Modélisation physique et analyse de stabilité (critère de Routh-Hurwitz). Identification expérimentale sur système réel (gain, constante de temps par réponse indicielle). Synthèse de régulateurs continus et numériques, en régulation cascade double boucle. Déploiement temps réel HIL sur cible Speedgoat (période d''échantillonnage 10ms). Résultats mesurés : temps de réponse divisé par 4 en boucle fermée, erreur statique annulée, robustesse validée face aux perturbations.', 'Temps de réponse divisé par 4 en boucle fermée, erreur statique annulée et robustesse de régulation validée sur banc d''essai matériel.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('filtre-tchebychev', 'fr', 'Filtre Passe-Bas Actif de Tchebychev', 'Électronique', 'De l''équation à la carte électronique fonctionnelle, conception, simulation et fabrication d''un filtre analogique.', 'Conception complète d''un filtre passe-bas actif d''ordre 4 de type Tchebychev, depuis la synthèse analytique jusqu''à la fabrication physique du PCB. Le projet inclut l''étude comparative Butterworth/Tchebychev, la simulation LTSpice, le routage KiCad complet et la caractérisation à l''oscilloscope du prototype final.', 'Synthèse analytique d''un filtre d''ordre 4 (comparaison Butterworth/Tchebychev) respectant un cahier des charges strict (bande passante 4,5 kHz, ondulation ≤1dB, atténuation 35dB à 13kHz). Simulation complète sous LTSpice avant fabrication. Routage KiCad de bout en bout : schéma, empreintes CMS, plan de masse, DRC, export Gerber. Fabrication physique : gravure CNC, soudure CMS, caractérisation à l''oscilloscope. Travail en binôme avec analyse comparative de deux réalisations indépendantes.', 'Prototype matériel entièrement fonctionnel, respectant strictement la fréquence de coupure à 4,5 kHz avec une atténuation effective de 35dB mesurée à l''oscilloscope.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('lyngk', 'fr', 'Lyngk – Moteur de Jeu Hexagonal', 'Algorithmique', 'Moteur de jeu de plateau hexagonal en C, entre rigueur bas niveau et algorithmique combinatoire.', 'Développement complet en langage C d''un moteur de jeu reproduisant fidèlement la mécanique du jeu de plateau Lyngk. L''architecture MVC stricte, avec modèle en Singleton, assure une séparation rigoureuse entre logique de jeu, rendu graphique SDL3 et gestion des entrées. Le plateau hexagonal est traité en coordonnées axiales avec un algorithme DFS pour le calcul de trajectoires.', 'Architecture MVC stricte (modèle en Singleton) pour un code maintenable. Optimisation bas niveau par bitmasking : 43 cases de plateau traitées en un seul cycle via registres 64 bits. Algorithme DFS pour le calcul de trajectoires en coordonnées axiales hexagonales. Gestion mémoire stricte : zéro fuite, compilation propre sous -Wall -Wextra. IA adverse (PvE) modélisée en machine d''état, sélection de coup en complexité O(1).', 'Moteur de jeu complet sans aucune fuite mémoire, permettant une résolution d''état asymétrique continue avec une complexité opérationnelle minimale.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('microprocesseurs', 'fr', 'Microprocesseurs & Programmation Bas Niveau', 'Informatique Bas Niveau', 'Trois systèmes embarqués en assembleur pur, sans aucune abstraction logicielle.', 'Développement de trois systèmes embarqués complets programmés exclusivement en assembleur AVR8 sur microcontrôleur ATMEGA2560, sans aucune bibliothèque ni abstraction logicielle. Chaque système exploite directement les registres matériels, les interruptions et les périphériques du microcontrôleur.', 'Compteur piloté par interruptions, avec mode veille pour l''économie d''énergie (zéro polling). Capteur de température interrogeable à distance, combinant CAN + port parallèle + USART simultanément. Système de détection d''intrusion (capteurs de distance, clavier matriciel, gestion d''événements concurrents type IoT).', 'Trois systèmes critiques (supervision, mesure de température embarquée, capteurs temps réel) développés avec une efficience mémoire native et une stabilité absolue des interruptions.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('robotino', 'fr', 'Robotino – Hockey Autonome', 'Systèmes Embarqués', 'Programmation d''un robot mobile omnidirectionnel pour un match de hockey entièrement autonome : vision, navigation et tir.', 'Conception complète du système de contrôle d''un Robotino 2 pour un match de hockey robotisé. Le robot devait repérer un palet par vision embarquée, naviguer vers le but en évitant les robots adverses, détecter la ligne de but métallique par capteur inductif et déclencher un tir précis. L''architecture de contrôle repose sur un Grafcet hiérarchique orchestrant navigation, évitement d''obstacles temps réel et séquence de tir.', 'La détection colorimétrique initiale en espace RGB générait des pertes de cible face aux variations lumineuses. Le basculement vers l''espace HSV a isolé la teinte de la luminosité pour un suivi robuste. La portée très courte du capteur inductif (4 mm) entraînait des dépassements de cible à cause de l''inertie. Une anticipation de freinage via odométrie (2000 impulsions/tour) et vision a résolu le problème. La zone fiable des infrarouges (15-45 cm) a été modélisée pour éviter les faux positifs au-delà de 50 cm.', 'Système de vision et de tir fiabilisé en conditions réelles de match, avec un suivi de palet robuste malgré les variations lumineuses et un tir déclenché sans dépassement de cible.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('awale', 'fr', 'Awale - Stratégie en C', 'Algorithmique', 'Développement du jeu de société traditionnel en langage C axé sur l''efficacité des structures.', 'Conception architecturale et implémentation en langage formel C de la mécanique combinatoire du jeu de société Awale. Ce projet focalise principalement sur la performance algorithmique pure, la gestion déterministe de la mémoire et la logique d''état asymétrique continue.', 'La difficulté majeure résidait dans la modélisation mathématique d''un plateau de jeu strictement cyclique sans causer de débordement dynamique en mémoire vive. L''approche d''ingénierie a consisté à encapsuler le plateau dans des structures de données contiguës, manipulées perpétuellement via l''arithmétique modulaire et des pointeurs de fonctions robustes.', 'Moteur de jeu s''exécutant dans un espace mémoire strictement borné, sans dépassement ni fuite, validé sur l''ensemble des scénarios de partie cyclique.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('pygroove', 'fr', 'PyGroove - Assistant Musical', 'Développement Logiciel', 'Lecteur musical intelligent en Python doté de reconnaissance vocale et de rendu audio synchrone.', 'Création d''un environnement de lecture multimédia intelligent programmé entièrement en Python. Le système orchestre une interface vectorielle complexe sous Tkinter, délègue le rendu bas niveau au moteur Pygame, intègre le protocole de reconnaissance vocale Speech-Recognition, et procède au parsing de métadonnées audio via les algorithmes Pydub et Mutagen.', 'Gérer la concurrence critique d''accès matériels simultanés entre la boucle d''événements visuels, le thread d''écoute réseau asynchrone et le buffer DMA matériel de la carte son. La solution logicielle a impliqué une séparation d''E/S (Entrées/Sorties) au sein d''une architecture multi-threadée stricte pour isoler les instructions temps réel du wrapper asynchrone.', 'Application stable en usage prolongé : lecture audio, reconnaissance vocale et interface graphique tournent simultanément sans blocage ni conflit d''accès matériel.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('terminal-c', 'fr', 'Shell Unix - Interpréteur C', 'Systèmes Embarqués', 'Développement natif complet d''un émulateur de terminal en langage C s''adossant aux appels Unix/Linux.', 'Ingénierie inverse d''un shell applicatif standard par la manipulation intime des appels système au niveau de l''espace noyau (Kernel Space). Ce projet requiert une compréhension profonde de la mémoire paginée (Heap), la duplication de processus système ainsi que l''interfaçage des descripteurs de fichiers.', 'La communication asynchrone et imprévisible inter-processus a provoqué des instabilités dans les flux d''entrées/sorties lors de la propagation du signal matériel. L''exécution sécurisée fut garantie par le déploiement d''un gestionnaire de signaux déterministes et la gestion méthodique des pipelines en mémoire vive (fork, execvp et dup2).', 'Shell capable d''exécuter des chaînes de commandes complexes (pipes, redirections) de façon stable, sans fuite de processus ni instabilité liée aux signaux système.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('ferme-poo', 'fr', 'Simulateur Agricole C++', 'Développement Logiciel', 'Application modélisée en C++ démontrant la rigueur des patrons de conception majeurs (POO).', 'Modélisation en C++ d''un environnement systémique simulé. Le paradigme Orienté Objet est exploité de fond en comble pour assurer un isolement strict des responsabilités par l''héritage d''interfaces, le polymorphisme applicatif et la compartimentation spatiale des objets d''activité.', 'L''instabilité inhérente aux pointeurs orphelins (Dangling Pointers) au sein d''une topologie circulaire forte a compromis initialement la destruction des entités par le processus courant. L''ingénierie moderne en C++ a remédié au conflit en déployant un écosystème de pointeurs intelligents gérant structurellement le cycle de vie mémoire via le comptage de références.', 'Architecture 100% exempte de fuite mémoire malgré une topologie d''objets fortement circulaire, grâce à une gestion du cycle de vie par pointeurs intelligents.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('snake', 'fr', 'Snake - Moteur Arcade C++', 'Algorithmique', 'Conception architecturale en C++ encadrant la complexité d''une boucle vidéo temps réel.', 'Développement fonctionnel d''un moteur d''arcade limitant la surcharge du microprocesseur selon des principes stricts de la POO. Implémentation isolée de la game loop principale, abstraction du module des entrées matérielles, et raffinement algorithmique pour la vérification collisionnelle 2D.', 'La chute du taux de rafraîchissement (frame rate drops) occasionnait des erreurs silencieuses dans le registre de vérifications d''intersections vectorielles à haute vélocité. Le correctif a dicté l''adoption d''un diviseur d''échelle temporel interpolé (Delta-time scaling) garantissant une cohérence arithmétique mathématiquement indépendante de la bande passante du processeur local.', 'Boucle de jeu maintenant une fréquence stable et une détection de collision fiable, indépendamment de la puissance du processeur cible.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('budget', 'fr', 'Analyse Financière Python', 'Développement Logiciel', 'Script algorithmique automatisant le traitement systématique de vastes cohortes de données statistiques mensuelles.', 'Conception et écriture d''une tuyauterie de données (data pipeline) robuste en Python. Ce module opère au travers de bibliothèques d''analyse complexes pour extraire, uniformiser, et générer mathématiquement des tracés graphiques interactifs en vue de synthèses prédictives.', 'La lenteur systémique de compilation générée par la traversée bouclée d''enregistrements historiques massifs limitait l''utilisation instantanée de la vue interface. La restructuration informatique a introduit une vectorisation matricielle stricte de toutes les manipulations, combinée à une sauvegarde délocalisée du tracé en tampons SVG/Canvas pré-rendus.', 'Temps de traitement des cohortes de données mensuelles réduit significativement grâce à la vectorisation, avec restitution graphique quasi instantanée.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('voiture-bluetooth', 'fr', 'Robot Mobile Bluetooth', 'Systèmes Embarqués', 'Déploiement en tant que Chef de Projet d''un système matériel piloté via Arduino (C/C++).', 'Ingénierie complète intégrée, couvrant l''analyse CAO et modélisation via CATIA V5, en tandem formel avec l''impression 3D paramétrique du bâti asymétrique de mobilité. Développement microcontrôlé en C/C++ (Arduino) de la chaîne de régulation motrice ainsi que de l''antenne logique de communication Bluetooth RX/TX bidirectionnelle.', 'Une sollicitation d''intensité hors normes au démarrage des unités moteurs provoquait d''importants creux de tension capacitifs perturbant directement les calculs logiques embarqués (brownouts hardware). L''architecture a été solidifiée grâce à un isolement galvanique partiel par optocoupleur et l''optimisation mathématique du routage de puissance via les signaux de commande en PWM (Pulse Width Modulation).', 'Robot livré et fonctionnel en conditions réelles, avec chaîne motrice stabilisée contre les micro-coupures de tension et liaison Bluetooth bidirectionnelle fiable.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('controle-hydraulique', 'en', 'Real-Time Control, Dual-Tank Hydraulic Process', 'Automation & Control', 'From Matlab/Simulink modeling to real-time control on an industrial Speedgoat target.', 'Complete control engineering project on a coupled dual-tank hydraulic system. From physical modeling and stability analysis to deployment of a real-time digital controller on a Speedgoat target, through experimental identification and synthesis of continuous and discrete controllers.', 'Physical modeling and stability analysis (Routh-Hurwitz criterion). Experimental identification on a real system (gain, time constant via step response). Continuous and digital controller synthesis, in dual-loop cascade control. Real-time HIL deployment on Speedgoat target (10ms sampling period). Measured results: response time divided by 4 in closed loop, static error eliminated, robustness validated against disturbances.', 'Closed-loop response time divided by 4, with zero steady-state error and validated robustness against perturbations on hardware target.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('filtre-tchebychev', 'en', 'Chebyshev Active Low-Pass Filter', 'Electronics', 'From equation to working circuit board, design, simulation, and fabrication of an analog filter.', 'Complete design of a 4th-order Chebyshev active low-pass filter, from analytical synthesis to physical PCB fabrication. The project includes a Butterworth/Chebyshev comparative study, LTSpice simulation, full KiCad routing, and oscilloscope characterization of the final prototype.', 'Analytical synthesis of a 4th-order filter (Butterworth/Chebyshev comparison) meeting strict specifications (4.5 kHz bandwidth, ≤1dB ripple, 35dB attenuation at 13kHz). Full simulation in LTSpice before fabrication. End-to-end KiCad routing: schematic, SMD footprints, ground plane, DRC, Gerber export. Physical fabrication: CNC milling, SMD soldering, oscilloscope characterization. Pair work with comparative analysis of two independent builds.', 'Prototype circuit board validated via instruments, meeting the required cutoff frequency and attenuation with sub-threshold ripple.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('lyngk', 'en', 'Lyngk – Hexagonal Game Engine', 'Algorithms', 'Hexagonal board game engine in C, blending low-level rigor with combinatorial algorithms.', 'Full development in C of a game engine faithfully reproducing the mechanics of the Lyngk board game. The strict MVC architecture, with a Singleton model, ensures rigorous separation between game logic, SDL3 graphical rendering, and input management. The hexagonal board is handled using axial coordinates with a DFS algorithm for trajectory computation.', 'Strict MVC architecture (Singleton model) for maintainable code. Low-level optimization via bitmasking: 43 board cells processed in a single cycle using 64-bit registers. DFS algorithm for trajectory computation in hexagonal axial coordinates. Strict memory management: zero leaks, clean compilation under -Wall -Wextra. Adversarial AI (PvE) modeled as a state machine, move selection in O(1) complexity.', 'Complete game engine with zero memory leaks, enabling continuous asymmetric state resolution with minimal operational complexity.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('microprocesseurs', 'en', 'Microprocessors & Low-Level Programming', 'Low-Level Computing', 'Three embedded systems in pure assembly, without any software abstraction.', 'Development of three complete embedded systems programmed exclusively in AVR8 assembly on ATMEGA2560 microcontroller, without any library or software abstraction. Each system directly exploits hardware registers, interrupts, and microcontroller peripherals.', 'Interrupt-driven counter with sleep mode for power saving (zero polling). Remotely queryable temperature sensor, combining ADC + parallel port + USART simultaneously. Intrusion detection system (distance sensors, matrix keypad, concurrent IoT-type event management).', 'Three critical systems (supervision, embedded temperature measurement, real-time sensors) functionally implemented with memory efficiency and absolute interrupt stability.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('robotino', 'en', 'Robotino – Autonomous Hockey', 'Embedded Systems', 'Programming an omnidirectional mobile robot for a fully autonomous hockey match: vision, navigation, and shooting.', 'Complete design of the control system of a Robotino 2 for a robotic hockey match. The robot had to locate a puck via embedded vision, navigate to the goal while avoiding opponents, detect the metallic goal line via inductive sensor, and trigger an accurate shot. The control architecture relies on a hierarchical Grafcet orchestrating navigation, real-time obstacle avoidance, and shooting sequence.', 'Initial colorimetric detection in RGB space generated target losses opposite to light variations. Switching to the HSV space isolated the hue from the brightness for robust tracking. The very short range of the inductive sensor (4 mm) led to target overshoots due to inertia. Braking anticipation via odometry and vision solved the problem. The reliable infrared zone (15-45 cm) was modeled to avoid false positives at a distance.', 'Vision and shooting system made reliable under real match conditions, with robust puck tracking despite lighting changes and shots triggered without target overshoot.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('awale', 'en', 'Awale - C Strategy', 'Algorithms', 'Development of the traditional board game in C language focused on data structure efficiency.', 'Architectural design and formal implementation in C language of the combinatorial mechanics of the Awale board game. This project focuses on pure algorithmic performance, deterministic memory management, and continuous asymmetric state logic.', 'The major difficulty lay in the mathematical modeling of a strictly cyclic game board without causing dynamic memory overflows in RAM. The engineering approach consisted of encapsulating the board in contiguous data structures continuously manipulated via modular arithmetic and robust function pointers.', 'Game engine running within a strictly bounded memory space, without overflow or leaks, validated across all cyclic game scenarios.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('pygroove', 'en', 'PyGroove - Music Assistant', 'Software Engineering', 'Intelligent Python music player with voice recognition and synchronous audio rendering.', 'Creation of an intelligent multimedia playback environment programmed entirely in Python. The system orchestrates a complex vector interface under Tkinter, delegates low-level rendering to the Pygame engine, integrates the Speech-Recognition protocol, and parses audio metadata via the Pydub and Mutagen algorithms.', 'Managing the critical concurrency of simultaneous hardware accesses between the visual event loop, the asynchronous network listening thread, and the sound card''s hardware DMA buffer. The software solution involved an I/O separation within a strict multi-threaded architecture to isolate real-time instructions from the asynchronous wrapper.', 'Stable application under extended use: audio playback, voice recognition, and the GUI all run simultaneously without freezing or hardware access conflicts.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('terminal-c', 'en', 'Unix Shell - C Interpreter', 'Embedded Systems', 'Full native development of a terminal emulator in C relying on Unix/Linux calls.', 'Reverse engineering of a standard application shell by intimately manipulating system calls at the Kernel Space level. This project requires a deep understanding of paged memory (Heap), system process duplication, and file descriptor interfacing.', 'Asynchronous and unpredictable inter-process communication caused instabilities in I/O streams during hardware signal propagation. Secure execution was ensured by deploying a deterministic signal handler and methodical management of RAM pipelines (fork, execvp, and dup2).', 'Shell able to execute complex command chains (pipes, redirections) reliably, without process leaks or signal-related instability.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('ferme-poo', 'en', 'C++ Farm Simulator', 'Software Engineering', 'C++ modeled application demonstrating the rigor of major OOP design patterns.', 'C++ modeling of a simulated systemic environment. The Object-Oriented paradigm is exploited thoroughly to ensure strict separation of responsibilities through interface inheritance, application polymorphism, and spatial compartmentalization of activity objects.', 'The instability inherent to dangling pointers within a strong circular topology initially compromised the destruction of entities by the current process. Modern C++ engineering remedied the conflict by deploying an ecosystem of smart pointers structurally managing the memory lifecycle via reference counting.', 'Fully leak-free architecture despite a strongly circular object topology, thanks to lifecycle management via smart pointers.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('snake', 'en', 'Snake - C++ Arcade Engine', 'Algorithms', 'C++ architectural design framing the complexity of a real-time video loop.', 'Functional development of an arcade engine limiting microprocessor overload according to strict OOP principles. Isolated implementation of the main game loop, abstraction of the hardware input module, and algorithmic refinement for 2D collision verification.', 'Frame rate drops caused silent errors in the register of high-velocity vector intersection checks. The fix dictated the adoption of an interpolated Delta-time scaling guaranteeing arithmetic consistency mathematically independent of the local processor bandwidth.', 'Game loop maintaining a stable frame rate and reliable collision detection, independent of the target processor''s power.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('budget', 'en', 'Python Finance Analytics', 'Software Engineering', 'Algorithmic script automating the systematic processing of vast cohorts of monthly statistical data.', 'Design and writing of a robust data pipeline in Python. This module operates through complex analysis libraries to extract, standardize, and mathematically generate interactive graphic plots for predictive syntheses.', 'The systemic compilation slowness generated by the looped traversal of massive historical records limited the instantaneous use of the interface view. The IT restructuring introduced a strict matrix vectorization of all manipulations, combined with off-site saving of the plot in pre-rendered SVG/Canvas buffers.', 'Processing time for monthly data cohorts significantly reduced through vectorization, with near-instant chart rendering.');
INSERT INTO project_translations (project_id, locale, title, category, short_description, detailed_description, technical_challenges, impact) VALUES ('voiture-bluetooth', 'en', 'Bluetooth Mobile Robot', 'Embedded Systems', 'Deployed as Project Manager of a hardware system controlled via Arduino (C/C++).', 'Complete integrated engineering, covering CAD analysis and modeling via CATIA V5, in formal tandem with parametric 3D printing of the asymmetric mobility frame. Microcontrolled development in C/C++ (Arduino) of the motor regulation chain as well as the logical bidirectional Bluetooth RX/TX communication antenna.', 'An extraordinary intensity solicitation upon starting the motor units caused significant capacitive voltage sags directly disrupting embedded logic calculations (hardware brownouts). The architecture was solidified through partial galvanic isolation by optocoupler and the mathematical optimization of power routing via PWM (Pulse Width Modulation) control signals.', 'Robot delivered and functional under real conditions, with a motor chain stabilized against voltage brownouts and a reliable bidirectional Bluetooth link.');
